SELECT ?zone ?zlabel ?sensor WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?zlabel .
  FILTER(STR(?zlabel) IN ("Core_bottom","Perimeter_bot_ZN_4","Perimeter_top_ZN_1"))
  OPTIONAL { ?zone brick:hasPoint ?sensor . ?sensor a brick:ElectricPowerSensor . }
}

SELECT ?sensor ?sclass ?tsid WHERE {
  ?sensor a brick:ElectricPowerSensor .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?tsid . }
  ?sclass ?s2 ?sensor .
} LIMIT 30

